  1  "use client";
  2  
  3  import { useCallback, useEffect, useRef, useState } from "react";
  4  
  5  import { ApiError, toApiError, type AuthInput } from "@/lib/api/client";
  6  import { useFrontendSession } from "@/components/providers/session-provider";
  7  
  8  /**
  9   * Async discipline for every workspace-scoped resource.
 10   *
 11   * A response is only applied when its (sessionId, resourceKey, request
 12   * generation) triple still matches the live one. That covers workspace
 13   * switches, selector switches, and A → B → A sequences where an older
 14   * request for the same resource would otherwise overwrite newer state.
 15   *
 16   * An API failure is kept as an error — it is never flattened into an
 17   * empty list, so pages can distinguish "failed" from "genuinely empty".
 18   */
 19  export type WorkspaceQuery<T> = {
 20    data: T | null;
 21    error: ApiError | null;
 22    loading: boolean;
 23    /** True only after a successful load for the current session + key. */
 24    loaded: boolean;
 25    reload: () => void;
 26  };
 27  
 28  export function useWorkspaceData<T>(
 29    load: (auth: AuthInput) => Promise<T>,
 30    /** Resource identity: changing it invalidates in-flight responses. */
 31    resourceKey: string,
 32    options?: { enabled?: boolean },
 33  ): WorkspaceQuery<T> {
 34    const { workspaceId, accessToken, connected, sessionId } = useFrontendSession();
 35    const enabled = options?.enabled ?? true;
 36  
 37    const [data, setData] = useState<T | null>(null);
 38    const [error, setError] = useState<ApiError | null>(null);
 39    const [loading, setLoading] = useState(false);
 40    const [loaded, setLoaded] = useState(false);
 41    const [reloadToken, setReloadToken] = useState(0);
 42  
 43    const loadRef = useRef(load);
 44    loadRef.current = load;
 45  
 46    // Live identity of the request the component still cares about.
 47    const activeRef = useRef({ sessionId, resourceKey, generation: 0 });
 48  
 49    useEffect(() => {
 50      activeRef.current = { sessionId, resourceKey, generation: activeRef.current.generation + 1 };
 51      setData(null);
 52      setError(null);
 53      setLoaded(false);
 54      setLoading(false);
 55    }, [sessionId, resourceKey]);
 56  
 57    useEffect(() => {
 58      if (!connected || !enabled || !resourceKey) return;
 59      const generation = (activeRef.current.generation += 1);
 60      const requestSessionId = sessionId;
 61      const requestKey = resourceKey;
 62      const isCurrent = () =>
 63        activeRef.current.sessionId === requestSessionId &&
 64        activeRef.current.resourceKey === requestKey &&
 65        activeRef.current.generation === generation;
 66  
 67      setLoading(true);
 68      setError(null);
 69      void (async () => {
 70        try {
 71          const result = await loadRef.current({ workspaceId, accessToken });
 72          if (!isCurrent()) return;
 73          setData(result);
 74          setLoaded(true);
 75        } catch (caught) {
 76          if (!isCurrent()) return;
 77          setError(toApiError(caught, ""));
 78          setData(null);
 79          setLoaded(false);
 80        } finally {
 81          if (isCurrent()) setLoading(false);
 82        }
 83      })();
 84    }, [connected, enabled, resourceKey, sessionId, workspaceId, accessToken, reloadToken]);
 85  
 86    const reload = useCallback(() => setReloadToken((token) => token + 1), []);
 87  
 88    return { data, error, loading, loaded, reload };
 89  }
 90  
 91  /**
 92   * Mutation guard with the same identity rules. The callback's result is
 93   * only applied while the session and resource are still the live ones,
 94   * so a slow mutation cannot write back after a workspace switch.
 95   */
 96  export function useWorkspaceMutation(resourceKey: string) {
 97    const { workspaceId, accessToken, sessionId } = useFrontendSession();
 98    const [pending, setPending] = useState(false);
 99    const [error, setError] = useState<ApiError | null>(null);
100  
101    const activeRef = useRef({ sessionId, resourceKey, generation: 0 });
102    activeRef.current.sessionId = sessionId;
103    activeRef.current.resourceKey = resourceKey;
104  
105    useEffect(() => {
106      activeRef.current = { sessionId, resourceKey, generation: activeRef.current.generation + 1 };
107      setPending(false);
108      setError(null);
109    }, [sessionId, resourceKey]);
110  
111    const run = useCallback(
112      async <T,>(
113        mutate: (auth: AuthInput) => Promise<T>,
114        onSuccess?: (result: T) => void,
115      ): Promise<T | null> => {
116        const generation = (activeRef.current.generation += 1);
117        const requestSessionId = sessionId;
118        const requestKey = resourceKey;
119        const isCurrent = () =>
120          activeRef.current.sessionId === requestSessionId &&
121          activeRef.current.resourceKey === requestKey &&
122          activeRef.current.generation === generation;
123  
124        setPending(true);
125        setError(null);
126        try {
127          const result = await mutate({ workspaceId, accessToken });
128          if (!isCurrent()) return null;
129          onSuccess?.(result);
130          return result;
131        } catch (caught) {
132          if (isCurrent()) setError(toApiError(caught, ""));
133          return null;
134        } finally {
135          if (isCurrent()) setPending(false);
136        }
137      },
138      [workspaceId, accessToken, sessionId, resourceKey],
139    );
140  
141    return { run, pending, error, clearError: useCallback(() => setError(null), []) };
142  }

