  3  /**
  4   * Runtime API client for the Agent Playground.
  5   *
  6   * This module speaks the `/agent-runs/**` runtime contract only. The
  7   * observability product API (`lib/runs.ts`, `/runs/**`) is a different
  8   * contract with a different response shape and is never mixed in here.
  9   */
 10  
 11  function runtimeBase(workspaceId: string): string {
 12    return `/api/v1/workspaces/${encodeURIComponent(workspaceId)}`;
 13  }
 14  
 15  /**
 16   * Authoritative runtime Run as persisted by the backend. After any
 17   * terminal stream event the UI re-reads this record and trusts it over
 18   * whatever the stream accumulated.
 19   */
 20  export type AgentRun = {
 21    id: string;
 22    workspace_id: string;
 23    agent_version_id: string;
 24    status: string;
 25    /**
 26     * Null for a reader who only holds `workspace_read`: the backend withholds
 27     * the raw prompt and the model's answer from anyone without `agent_run`.
 28     * The fields stay present in the contract; only their content is gated.
 29     */
 30    input_text: string | null;
 31    final_output: string | null;
 32    failure_code: string | null;
 33    resolved_spec_hash: string | null;
 34    /** One entry per resolved knowledge snapshot, not a keyed object. */
 35    effective_knowledge_snapshots: Array<Record<string, unknown>>;
 36    model_step_count: number;
 37    tool_call_count: number;
 38    total_input_tokens: number | null;
 39    total_output_tokens: number | null;
 40    total_tokens: number | null;
 41    total_cached_tokens: number | null;
 42    /** Decimal on the wire: it may arrive as a number or a string. */
 43    total_cost_amount: number | string | null;
 44    cost_currency: string | null;
 45    cost_is_estimate: boolean | null;
 46    created_by: string;
 47    created_at: string;
 48    /** A persisted run has always started; only completion is optional. */
 49    started_at: string;
 50    completed_at: string | null;
 51  };
 52  
 53  export function getAgentRun(input: AuthInput, runId: string): Promise<AgentRun> {
 54    return apiRequest<AgentRun>(
 55      `${runtimeBase(input.workspaceId)}/agent-runs/${encodeURIComponent(runId)}`,
 56      input.accessToken,
 57    );
 58  }
 59  
 60  /**
 61   * Creates a new non-streaming run for a published agent version.
 62   *
 63   * Replay uses this: it is a brand new run with its own id, not a resume
 64   * of an existing one. The backend decides everything else, including
 65   * whether the new run pauses for approval.
 66   */
 67  export function createAgentRun(
 68    input: AuthInput,
 69    options: { agentVersionId: string; inputText: string },
 70  ): Promise<AgentRun> {
 71    return apiRequest<AgentRun>(
 72      `${runtimeBase(input.workspaceId)}/agent-versions/` +
 73        `${encodeURIComponent(options.agentVersionId)}/runs`,
 74      input.accessToken,
 75      { method: "POST", body: { input_text: options.inputText } },
 76    );
 77  }
 78  
 79  /**
 80   * Asks the backend to stop the run. The result may legitimately still be
 81   * CANCEL_REQUESTED — that is a request in flight, not a cancelled run.
 82   */
 83  export function cancelAgentRun(input: AuthInput, runId: string): Promise<AgentRun> {
 84    // apiRequest uses the session provider's single-flight 401 refresh/replay.
 85    return apiRequest<AgentRun>(
 86      `${runtimeBase(input.workspaceId)}/agent-runs/${encodeURIComponent(runId)}/cancel`,
 87      input.accessToken,
 88      { method: "POST", body: {} },
 89    );
 90  }
 91  
 92  /** Frozen runtime event vocabulary. No client-invented types are accepted. */
 93  export const AGENT_EVENT_TYPES = [
 94    "run.started",
 95    "message.started",
 96    "context.budget",
 97    "message.delta",
 98    "message.completed",
 99    "retrieval.started",
100    "retrieval.completed",
101    "rerank.completed",
102    "tool.requested",
103    "tool.started",
104    "tool.completed",
105    "tool.failed",
106    "approval.required",
107    "approval.resolved",
108    "run.cancel_requested",
109    "usage",
110    "run.completed",
111    "run.failed",
112    "run.cancelled",
113  ] as const;
114  
115  export type AgentEventType = (typeof AGENT_EVENT_TYPES)[number];
116  
117  export type AgentEvent = {
118    event_id: string;
119    type: AgentEventType;
120    request_id: string;
121    run_id: string;
122    step_id: string | null;
123    timestamp: string;
124    payload: Record<string, unknown>;
125    sequence: number;
126    agent_version_id: string;
127  };
128  
129  /** Raised for any frame the runtime contract cannot explain. */
130  export function streamProtocolError(message: string): ApiError {
131    return new ApiError("STREAM_PROTOCOL_ERROR", message, 0);
132  }
133  
134  function isKnownEventType(value: string): value is AgentEventType {
135    return (AGENT_EVENT_TYPES as readonly string[]).includes(value);
136  }
137  
138  /**
139   * One decoded SSE frame. `comment` frames (`: heartbeat`) carry no data
140   * field and are never business events.
141   */
142  type SseFrame = { event: string | null; data: string | null };
143  
144  function decodeFrame(raw: string): SseFrame {
145    let event: string | null = null;
146    const dataLines: string[] = [];
147    for (const line of raw.split("\n")) {
148      // A leading colon marks a comment; heartbeats arrive exactly this way.
149      if (line === "" || line.startsWith(":")) continue;
150      const colon = line.indexOf(":");
151      const field = colon === -1 ? line : line.slice(0, colon);
152      let value = colon === -1 ? "" : line.slice(colon + 1);
153      if (value.startsWith(" ")) value = value.slice(1);
154      if (field === "event") event = value;
155      else if (field === "data") dataLines.push(value);
156    }
157    return { event, data: dataLines.length > 0 ? dataLines.join("\n") : null };
158  }
159  
160  /**
161   * Validates one frame against the frozen AgentEvent contract.
162   * Returns null for heartbeats and other dataless frames; throws a
163   * STREAM_PROTOCOL_ERROR for frames that claim to be events but are not.
164   */
165  export function parseAgentEventFrame(raw: string): AgentEvent | null {
166    const frame = decodeFrame(raw);
167    if (frame.data === null) return null;
168  
169    let parsed: unknown;
170    try {
171      parsed = JSON.parse(frame.data);
172    } catch {
173      throw streamProtocolError("A stream frame contained data that is not valid JSON.");
174    }
175    if (!isRecord(parsed)) {
176      throw streamProtocolError("A stream frame contained data that is not an object.");
177    }
178    if (typeof parsed.type !== "string") {
179      throw streamProtocolError("A stream event is missing its type.");
180    }
181    if (!isKnownEventType(parsed.type)) {
182      throw streamProtocolError(`A stream event used an unknown type: ${parsed.type}`);
183    }
184    if (typeof parsed.run_id !== "string") {
185      throw streamProtocolError("A stream event is missing its run id.");
186    }
187    if (typeof parsed.sequence !== "number") {
188      throw streamProtocolError("A stream event is missing its sequence.");
189    }
190    if (!isRecord(parsed.payload)) {
191      throw streamProtocolError("A stream event is missing its payload object.");
192    }
193    return {
194      event_id: typeof parsed.event_id === "string" ? parsed.event_id : "",
195      type: parsed.type,
196      request_id: typeof parsed.request_id === "string" ? parsed.request_id : "",
197      run_id: parsed.run_id,
198      step_id: typeof parsed.step_id === "string" ? parsed.step_id : null,
199      timestamp: typeof parsed.timestamp === "string" ? parsed.timestamp : "",
